import {SphereWebGLRenderer} from '../../src/rendering/spherical-webgl.ts';
import {SphericalSession} from '../../src/editor/spherical-session.ts';
import type {RoundedCrescentSession} from '../../src/editor/rounded-crescent-session.ts';
import {projectSphere,type SphericalView} from '../../src/rendering/spherical-view.ts';
import {createRoundedCrescentWorld} from '../../src/terrain/rounded-crescent-globe.ts';
import {startSphericalBrushStroke,type SphericalBrushSettings,type SphericalBrushVisibility} from '../../src/terrain/spherical-brush.ts';
import {unitDirection,type Vec3} from '../../src/surfaces/cube-sphere.ts';
const registry=globalThis as unknown as {__roundedObserver?:{active?:RoundedCrescentSession;gpu?:SphereWebGLRenderer}},shared=registry.__roundedObserver??={};
const present=SphereWebGLRenderer.prototype.present;SphereWebGLRenderer.prototype.present=function(...args){if((this as unknown as {canvas:HTMLCanvasElement}).canvas.classList.contains('sphere-gpu'))shared.gpu=this;return present.apply(this,args);};
const update=SphericalSession.prototype.updateDisplay;SphericalSession.prototype.updateDisplay=function(){if(this.roundedGlobe)shared.active=this as RoundedCrescentSession;return update.call(this);};
export const current=()=>{if(!shared.active)throw Error('Rounded Crescent not active.');return shared.active;};
export const canvas=()=>document.querySelector<HTMLCanvasElement>('canvas[aria-label="Atlas Rounded Crescent Globe terrain map"]')!;
export function view():SphericalView {const d=canvas().dataset;return{mode:d.mode as 'globe'|'net',frame:JSON.parse(d.frame!),zoom:Number(d.zoom),pan:JSON.parse(d.pan!),roundedGlobe:current().world.geometry};}
export function snapshot(){const s=current(),d=canvas().dataset;return{ready:d.ready==='true',viewPending:d.viewPending==='true',displayPending:d.displayPending==='true',painting:s.painting,processing:s.processing,pending:s.pendingPoints,revision:s.terrain.revision,displayRevision:Number(d.displayRevision),renderer:d.renderer,diagnostics:JSON.parse(d.displayDiagnostics??'{}'),geometry:shared.gpu?.roundedStatistics,statistics:s.statistics,work:s.workDiagnostics,historyEntries:s.history.length,historyBytes:s.history.retainedBytes,configuration:s.world.geometry,view:view()};}
export async function hash(){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',current().terrain.copyElevations().buffer as ArrayBuffer)),v=>v.toString(16).padStart(2,'0')).join('');}
export function point(direction:Vec3){const c=canvas(),r=c.getBoundingClientRect(),p=projectSphere(current().terrain,direction,view(),{width:r.width,height:r.height})[0];return p?{x:r.left+p.x,y:r.top+p.y}:null;}
export function path(region:'inner'|'outer'|'upper'|'lower'|'first-tip'|'second-tip'|'seam',count=24,extent=.12,visibleOnly=false){return Array.from({length:count+1},(_,i)=>{const t=(i/count-.5)*(region==='first-tip'||region==='second-tip'?Math.max(extent,.6):extent),raw:Vec3=region==='inner'?[t,-1,0]:region==='outer'?[t,1,0]:region==='upper'?[t,0,1]:region==='lower'?[t,0,-1]:region==='first-tip'?[1,t,0]:region==='second-tip'?[-1,t,0]:[1+t,1-t,.04],p=point(unitDirection(raw));if(!p&&!visibleOnly)throw Error(`Rounded ${region} point ${i} is hidden`);return p;}).filter((p):p is NonNullable<typeof p>=>!!p);}
let recording=false,source:Float32Array,first:Vec3|undefined,settings:SphericalBrushSettings,hemisphere:Vec3|undefined,points:{direction:Vec3;visibility?:SphericalBrushVisibility}[]=[];
const begin=SphericalSession.prototype.begin,move=SphericalSession.prototype.move;
SphericalSession.prototype.begin=function(d,s,h){const accepted=begin.call(this,d,s,h);if(this.roundedGlobe&&recording&&accepted){first=structuredClone(d);settings={...s};hemisphere=h&&structuredClone(h);}return accepted;};
SphericalSession.prototype.move=function(d,v){if(this.roundedGlobe&&recording&&this.painting&&!this.processing&&!this.locked)points.push({direction:structuredClone(d),visibility:v&&structuredClone(v)});move.call(this,d,v);};
export function record(){source=current().terrain.copyElevations();first=undefined;points=[];recording=true;}
export function compare(){recording=false;if(!first)throw Error('No accepted rounded stroke.');const s=current(),m=s.terrain.metadata,world=createRoundedCrescentWorld({terrainId:m.terrainId,identity:m.identity,dimensions:s.world.geometry,detail:m.representation.cellsPerEdge as 128|256}),t=world.terrain;for(let i=0;i<source.length;i++)t.write(t.keyAt(i),source[i]!);const stroke=startSphericalBrushStroke(t,{...m.identity,direction:first},settings,undefined,hemisphere?{hemisphere}:undefined,{roundedGlobe:s.world.geometry});for(const p of points)stroke.moveTo({...m.identity,direction:p.direction},p.visibility);stroke.end();const actual=new Uint32Array(s.terrain.copyElevations().buffer),expected=new Uint32Array(t.copyElevations().buffer),before=new Uint32Array(source.buffer);let mismatches=0,changed=0;for(let i=0;i<actual.length;i++){if(actual[i]!==expected[i])mismatches++;if(actual[i]!==before[i])changed++;}return{mismatches,changed,accepted:points.length+1,statistics:stroke.statistics};}
export function renderCurrentGPU(){if(!shared.gpu?.available)throw Error('Current hardware renderer unavailable.');shared.gpu.copyCurrentRoundedFrame();return shared.gpu;}

export function visiblePath(region:Parameters<typeof path>[0]){return path(region,24,.12,true); }
